mapper.select:
SELECT id, doc_id, version, kb_id, tenant_id, user_id, agent_id, title, content,
       status, error_msg, created_at, updated_at
FROM kb_document
WHERE doc_id = #{docId}
  AND version = #{version}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}
LIMIT 1

SELECT MAX(version)
FROM kb_document
WHERE doc_id = #{docId}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}

mapper.update:
UPDATE kb_document
SET status = #{status},
    error_msg = #{errorMsg}
WHERE doc_id = #{docId}
  AND version = #{version}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}

UPDATE kb_document
SET status = 'ARCHIVED',
    error_msg = NULL
WHERE doc_id = #{docId}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND status = 'SUCCESS'
